import AppKit
import CryptoKit

/// Only inert clipboard representations are retained. No files are read or downloaded.
public struct ClipboardSnapshot: Codable, Equatable {
    public static let maximumBytes = 4 * 1_024 * 1_024
    public static let ignoredTypes: Set<String> = [
        "org.nspasteboard.TransientType", "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
        "com.typeit4me.clipping", "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type", "net.antelle.keeweb"
    ]
    public let items: [[String: Data]]

    public init(items: [[String: Data]]) { self.items = items }

    public init?(pasteboard: NSPasteboard) {
        let types = Set((pasteboard.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes) else { return nil }
        let allowed: [NSPasteboard.PasteboardType] = [.string, .rtf, .html, .png, .tiff, .fileURL, .URL]
        var captured: [[String: Data]] = []
        var total = 0
        let initialCount = pasteboard.changeCount
        for item in pasteboard.pasteboardItems ?? [] {
            guard Set(item.types.map(\.rawValue)).isDisjoint(with: Self.ignoredTypes) else { return nil }
            var representations: [String: Data] = [:]
            for type in allowed where item.types.contains(type) {
                // PNG and TIFF are interchangeable image fallbacks; keep one to avoid doubling memory.
                if type == .tiff, representations[NSPasteboard.PasteboardType.png.rawValue] != nil { continue }
                guard let data = item.data(forType: type) else { continue }
                total += data.count
                guard total <= Self.maximumBytes else { return nil }
                representations[type.rawValue] = data
            }
            // Never silently truncate a mixed or multi-file clipboard.
            guard !representations.isEmpty else { return nil }
            captured.append(representations)
        }
        guard !captured.isEmpty, initialCount == pasteboard.changeCount else { return nil }
        self.items = captured
    }

    public var byteCount: Int { items.reduce(0) { $0 + $1.values.reduce(0) { $0 + $1.count } } }
    public var text: String? {
        items.compactMap { $0[NSPasteboard.PasteboardType.string.rawValue] }
            .compactMap { String(data: $0, encoding: .utf8) }.first
    }
    public var imageData: Data? {
        items.first?[NSPasteboard.PasteboardType.png.rawValue]
            ?? items.first?[NSPasteboard.PasteboardType.tiff.rawValue]
    }
    public var kind: String {
        if items.contains(where: { $0[NSPasteboard.PasteboardType.fileURL.rawValue] != nil }) { return "file" }
        if imageData != nil { return "image" }
        return "text"
    }
    public var title: String {
        if kind == "file" {
            let paths = items.compactMap { $0[NSPasteboard.PasteboardType.fileURL.rawValue] }
                .compactMap { String(data: $0, encoding: .utf8) }
                .compactMap { URL(string: $0)?.lastPathComponent }
            return paths.joined(separator: ", ")
        }
        if kind == "image" { return "Copied image" }
        let value = text ?? items.first?[NSPasteboard.PasteboardType.URL.rawValue]
            .flatMap { String(data: $0, encoding: .utf8) } ?? "Formatted text"
        return String(value.trimmingCharacters(in: .whitespacesAndNewlines).prefix(500))
    }
    public var fingerprint: String {
        var hash = SHA256()
        func append(_ data: Data) {
            var length = UInt64(data.count).bigEndian
            withUnsafeBytes(of: &length) { hash.update(data: Data($0)) }
            hash.update(data: data)
        }
        for item in items {
            append(Data("item".utf8))
            for key in item.keys.sorted() {
                append(Data(key.utf8))
                append(item[key]!)
            }
        }
        return hash.finalize().map { String(format: "%02x", $0) }.joined()
    }

    @discardableResult
    public func write(to pasteboard: NSPasteboard) -> Bool {
        guard !items.isEmpty else { return false }
        var values: [NSPasteboardItem] = []
        for representations in items {
            guard !representations.isEmpty else { return false }
            let item = NSPasteboardItem()
            for (type, data) in representations {
                guard item.setData(data, forType: .init(type)) else { return false }
            }
            values.append(item)
        }
        pasteboard.clearContents()
        return pasteboard.writeObjects(values)
    }
}
